package utils

import (
	"context"
	"fmt"

	"github.com/vishvananda/netlink"
	"golang.org/x/sys/unix"
)

// LegacyVLANFilters returns only the VLAN push/pop filters generated by Terway.
// It deliberately excludes BPF filters, QoS filters and the shared clsact qdisc.
func LegacyVLANFilters(link netlink.Link) ([]netlink.Filter, error) {
	qdiscs, err := netlink.QdiscList(link)
	if err != nil {
		return nil, err
	}
	hasClsact := false
	for _, qdisc := range qdiscs {
		if qdisc.Type() == "clsact" {
			hasClsact = true
		}
	}
	if !hasClsact {
		return nil, nil
	}
	var result []netlink.Filter
	for _, parent := range []uint32{netlink.HANDLE_MIN_INGRESS, netlink.HANDLE_MIN_EGRESS} {
		filters, err := netlink.FilterList(link, parent)
		if err != nil {
			return nil, fmt.Errorf("list VLAN filters on %s: %w", link.Attrs().Name, err)
		}
		for _, filter := range filters {
			if isLegacyVLANFilter(filter, link.Attrs().Index, parent) {
				result = append(result, filter)
			}
		}
	}
	return result, nil
}

func isLegacyVLANFilter(filter netlink.Filter, index int, parent uint32) bool {
	u32, ok := filter.(*netlink.U32)
	if !ok || u32.LinkIndex != index || u32.Parent != parent || u32.Sel == nil || len(u32.Actions) != 1 || u32.ClassId != 0 || u32.RedirIndex != 0 {
		return false
	}
	action, ok := u32.Actions[0].(*netlink.VlanAction)
	if !ok {
		return false
	}
	sel := u32.Sel
	if sel.Flags != netlink.TC_U32_TERMINAL || int(sel.Nkeys) != len(sel.Keys) || sel.Offshift != 0 || sel.Offmask != 0 || sel.Off != 0 || sel.Offoff != 0 || sel.Hoff != 0 || sel.Hmask != 0 {
		return false
	}
	if parent == netlink.HANDLE_MIN_INGRESS {
		return u32.Priority == 20000 && u32.Protocol == uint16(netlink.VLAN_PROTOCOL_8021Q) &&
			action.Action == netlink.TCA_VLAN_KEY_POP && action.Attrs().Action == netlink.TC_ACT_RECLASSIFY &&
			len(sel.Keys) == 1 && sel.Keys[0] == (netlink.TcU32Key{})
	}
	if action.Action != netlink.TCA_VLAN_KEY_PUSH || action.Attrs().Action != netlink.TC_ACT_PIPE || action.Vid == 0 || action.Vid > 4094 {
		return false
	}
	var offsets []int32
	switch u32.Protocol {
	case unix.ETH_P_IP:
		if u32.Priority != 50001 {
			return false
		}
		offsets = []int32{12}
	case unix.ETH_P_IPV6:
		// Older versions shared the IPv4 priority for IPv6.
		if u32.Priority != 50001 && u32.Priority != 50002 {
			return false
		}
		offsets = []int32{8, 12, 16, 20}
	default:
		return false
	}
	if len(sel.Keys) != len(offsets) {
		return false
	}
	for i, off := range offsets {
		if sel.Keys[i].Off != off || sel.Keys[i].Mask != ^uint32(0) || sel.Keys[i].OffMask != 0 {
			return false
		}
	}
	return true
}

// RemoveLegacyVLANFilters requires the caller to drain workloads and serialize
// with CNI ADD/DEL before deleting the shared ingress rule.
func RemoveLegacyVLANFilters(ctx context.Context, filters []netlink.Filter) error {
	for _, filter := range filters {
		if err := FilterDel(ctx, filter); err != nil {
			return fmt.Errorf("remove legacy VLAN filter: %w", err)
		}
	}
	return nil
}
